solution:
use xiom.io;

type CartItem = {
  product: Str;
  price: Float64;
  quantity: Int;
}

fn CartItem.total(self) -> Float64 {
  return price * (quantity as Float64);
}

fn CartItem.format(self) -> Str {
  return product + " x" + quantity + " = $" + self.total();
}

fn main() -> Int {
  let milk = CartItem{ product: "Whole Milk"; price: 3.49; quantity: 2; };
  let bread = CartItem{ product: "Sourdough Bread"; price: 5.99; quantity: 1; };
  let eggs = CartItem{ product: "Free-Range Eggs"; price: 4.50; quantity: 3; };
  let grand = milk.total() + bread.total() + eggs.total();
  return (grand * 100.0) as Int;
}
